    )

    if ($Fast -and $Consistent) {
        throw 'backupf: -Fast and -Consistent cannot be used together. Verified logical consistency is the default.'
    }

    $sourceRoot = 'F:\'
    $destinationRoot = 'C:\fdrive'
    $metadataRoot = Join-Path $destinationRoot '.fdrive-backup'
    $manifestPath = Join-Path $metadataRoot 'manifest.json'
    $completePath = Join-Path $metadataRoot 'complete.json'
    $inProgressPath = Join-Path $metadataRoot 'in-progress.json'
    $copyOptions = @(
        '/E', '/MT:64', '/R:1', '/W:1', '/J',
        '/COPY:DAT', '/DCOPY:DA', '/XJ',
